 dark:{id:"curse",name:"呪い",chance:.43,turns:3,power:.03},
 light:{id:"stun",name:"気絶",chance:.20,turns:1,power:0},
 earth:{id:"stun",name:"気絶",chance:.22,turns:1,power:0},
